raw = json.load(open("scratch/b36_r08_raw_p5.json"))
by_id = {f"lex.en.200k.{x['id']}": x for x in records}
out = []
for orig in raw:
    r = by_id[orig["id"]]
    assert orig["hw"] == r["hw"], f"{orig['id']}: {orig['hw']} vs {r['hw']}"
    assert 0 < len(r["vi"]) <= 35, f"{r['id']} {r['hw']} len={len(r['vi'])}"
    assert "/" not in r["vi"], f"{r['id']} {r['hw']} slash in vi"
    assert r["ipa"].count("/") == 2, f"{r['id']} {r['hw']} bad ipa"
    orig["pos"] = r["pos"]
    orig["ipa"] = r["ipa"]
    orig["vi"] = r["vi"]
    orig["status"] = "reviewed"
    out.append(orig)
with open("scratch/b36_r08_p5.json", "w") as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
print(f"Saved scratch/b36_r08_p5.json ({len(out)} records)")
